CREATE TABLE host(hostname TEXT NOT NULL PRIMARY KEY, consoleHost TEXT, consolePort TEXT); INSERT INTO host VALUES('aald04','aalp03','4'); INSERT INTO host VALUES('aald17','aalp01','1'); CREATE VIEW consolemap1a AS SELECT hostname, consolehost, '/dev/cuaD0.' || (consoleport-1) AS consoleport FROM host WHERE consolehost='aalp01'; CREATE VIEW consolemap1b AS SELECT hostname AS hostname, consolehost AS consolehost, '/dev/cuaD' || substr('01',1+((consoleport-1)/16),1) || substr('0123456789abcdef',1+((consoleport-1)%16),1) AS consoleport FROM host WHERE consolehost='aalp03'; CREATE VIEW consolemap1 AS SELECT * FROM consolemap1a UNION SELECT * FROM consolemap1b; CREATE TABLE result AS SELECT * FROM consolemap1b;